type missingFlags map[string]string

func (m missingFlags) list() string {
	names := make([]string, 0, len(m))
	for name, value := range m {
		if value == "" {
			names = append(names, "--"+name)
		}
	}
	// Stable reporting order independent of map iteration.
	order := []string{"--registry", "--batch", "--product", "--quantity", "--unit"}
	var out []string
	for _, flagName := range order {
		for _, name := range names {
			if name == flagName {
				out = append(out, name)
			}
		}
	}
	return joinComma(out)
}

func joinComma(items []string) string {
	out := ""
	for i, item := range items {
		if i > 0 {
			out += ", "
		}
		out += item
	}
	return out
}

func fsUsage(fs *flag.FlagSet) string {
	return "usage: govflow batch-register --registry FILE --batch ID --product ID --quantity N --unit UNIT\n" +
		"run `govflow help` for the full description and the registry file format.\n"
}

