		"zero quantity":  `{"version":1,"batches":[{"batch":"B","product":"P","quantity":0,"unit":"kg"}]}`,
		"empty unit":     `{"version":1,"batches":[{"batch":"B","product":"P","quantity":1,"unit":""}]}`,
